INSERT INTO `psyc_test` (`id`, `test_name`, `description`, `status`, `total_questions`, `duration`, `create_time`, `update_time`) VALUES (1, '自我接纳问卷', '自我接纳指的是一个人对自己的特点、弱点、错误、无能和不足等方面的认知和接受程度。自我接受度越高，个体则越有可能体验到正向情绪如幸福、满足、自尊等，同时也更有可能建立起稳定和良好的关系。自我接纳问卷（The Self Acceptance Questionnaire，SAQ）由国内学者丛中等人于1999年开发，包括自我评价和自我接纳两个维度，用于反应个体的自我接纳水平。', 1, 16, 2, '2025-10-23 13:37:27', '2025-11-21 14:07:01');
INSERT INTO `psyc_test` (`id`, `test_name`, `description`, `status`, `total_questions`, `duration`, `create_time`, `update_time`) VALUES (2, '抑郁自评量表', '抑郁自评量表(Self-Rating Depression Scale， SDS)由W.K.Zung编制于1965年，为美国教育卫生福利部推荐的用于精神药理学研究的量表之一，SDS使用简便，能直观地反映病人抑郁的主观感受及其在治疗中的变化，广泛应用于门诊病人的粗筛、情绪状态评定以及调查科研等，适用于具有抑郁症状的成年人。', 1, 20, 2, '2026-04-21 14:18:51', '2026-04-21 14:56:28');
