INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (100, '创建表', 0, 'com.ruoyi.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"sql\":\"CREATE TABLE psyc_test (\\n    id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT \'测评项目ID\',\\n    test_name VARCHAR(100) NOT NULL COMMENT \'测评项目名称\',\\n    description TEXT COMMENT \'测评简介\',\\n    status TINYINT DEFAULT 1 COMMENT \'状态：0停用 1启用\',\\n    total_questions INT DEFAULT 0 COMMENT \'题目数量\',\\n    duration INT DEFAULT 30 COMMENT \'测评时长（分钟）\',\\n    create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT \'创建时间\',\\n    update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\'\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'心理测评项目表\';\"}', '{\"msg\":\"创建表结构异常\",\"code\":500}', 0, NULL, '2025-10-22 08:26:34', 32);
