INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (110, '心理测评项目', 1, 'com.ruoyi.web.controller.psyc.PsycTestController.add()', 'POST', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-10-23 13:37:27\",\"description\":\"自我接纳指的是一个人对自己的特点、弱点、错误、无能和不足等方面的认知和接受程度。自我接受度越高，个体则越有可能体验到正向情绪如幸福、满足、自尊等，同时也更有可能建立起稳定和良好的关系。自我接纳问卷（The Self Acceptance Questionnaire，SAQ）由国内学者丛中等人于1999年开发，包括自我评价和自我接纳两个维度，用于反应个体的自我接纳水平。\",\"duration\":2,\"id\":1,\"params\":{},\"testName\":\"自我接纳问卷\",\"totalQuestions\":16}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-10-23 05:37:27', 39);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (111, '心理测评项目', 2, 'com.ruoyi.web.controller.psyc.PsycTestController.edit()', 'PUT', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-10-23 13:37:27\",\"description\":\"自我接纳指的是一个人对自己的特点、弱点、错误、无能和不足等方面的认知和接受程度。自我接受度越高，个体则越有可能体验到正向情绪如幸福、满足、自尊等，同时也更有可能建立起稳定和良好的关系。自我接纳问卷（The Self Acceptance Questionnaire，SAQ）由国内学者丛中等人于1999年开发，包括自我评价和自我接纳两个维度，用于反应个体的自我接纳水平。\",\"duration\":2,\"id\":1,\"params\":{},\"status\":1,\"testName\":\"自我接纳问卷\",\"totalQuestions\":16,\"updateTime\":\"2025-10-23 14:33:02\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-10-23 06:33:02', 33);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (112, '创建表', 0, 'com.ruoyi.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"sql\":\"CREATE TABLE IF NOT EXISTS psyc_questions (\\n    id INT AUTO_INCREMENT PRIMARY KEY COMMENT \'题目ID\',\\n    content TEXT NOT NULL COMMENT \'题目内容\',\\n    type ENUM(\'single\', \'multiple\', \'judgment\', \'fill\', \'essay\') NOT NULL COMMENT \'题目类型：single-单选题，multiple-多选题，judgment-判断题，fill-填空题，essay-简答题\',\\n    category_id INT NOT NULL COMMENT \'所属分类ID\',\\n    difficulty ENUM(\'easy\', \'medium\', \'hard\') NOT NULL COMMENT \'难度：easy-简单，medium-中等，hard-困难\',\\n    analysis TEXT COMMENT \'解析内容\',\\n    source VARCHAR(100) COMMENT \'题目来源\',\\n    created_by INT NOT NULL COMMENT \'创建人ID\',\\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT \'创建时间\',\\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\',\\n    deleted_at TIMESTAMP NULL COMMENT \'删除时间\',\\n    KEY idx_category_id (category_id),\\n    KEY idx_type (type),\\n    KEY idx_difficulty (difficulty),\\n    KEY idx_created_by (created_by),\\n    KEY idx_created_at (created_at)\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'题目表\';\\n\\nCREATE TABLE IF NOT EXISTS psyc_options (\\n    id INT AUTO_INCREMENT PRIMARY KEY COMMENT \'选项ID\',\\n    question_id INT NOT NULL COMMENT \'题目ID\',\\n    content TEXT NOT NULL COMMENT \'选项内容\',\\n    sort_order INT NOT NULL COMMENT \'排序顺序\',\\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT \'创建时间\',\\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\',\\n    KEY idx_question_id (question_id)\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'题目选项表\';\\n\\nCREATE TABLE IF NOT EXISTS psyc_question_answers (\\n    id INT AUTO_INCREMENT PRIMARY KEY COMMENT \'答案ID\',\\n    question_id INT NOT NULL COMMENT \'题目ID\',\\n    option_id INT NULL COMMENT \'选项ID（选择题）\',\\n    content TEXT NULL COMMENT \'答案内容（填空题、简答题）\',\\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT \'创建时间\',\\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\',\\n    KEY idx_question_id (question_id),\\n    KEY idx_option_id (option_id)\\n) ENGINE', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-10-23 07:20:54', 4576);
