INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (121, '心理测评', 2, 'com.ruoyi.web.controller.psyc.PsycTestController.edit()', 'PUT', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-10-23 13:37:27\",\"description\":\"自我接纳指的是一个人对自己的特点、弱点、错误、无能和不足等方面的认知和接受程度。自我接受度越高，个体则越有可能体验到正向情绪如幸福、满足、自尊等，同时也更有可能建立起稳定和良好的关系。自我接纳问卷（The Self Acceptance Questionnaire，SAQ）由国内学者丛中等人于1999年开发，包括自我评价和自我接纳两个维度，用于反应个体的自我接纳水平。\",\"duration\":2,\"id\":1,\"params\":{},\"psycQuestionsList\":[{\"analysis\":\"\",\"content\":\"1\",\"createdAt\":\"2025-10-24\",\"createdBy\":1,\"deletedAt\":\"2025-10-24\",\"difficulty\":\"\",\"params\":{},\"source\":\"科学网\",\"testId\":1,\"type\":\"multiple\",\"updatedAt\":\"2025-10-24\"}],\"status\":1,\"testName\":\"自我接纳问卷\",\"totalQuestions\":16,\"updateTime\":\"2025-10-24 22:05:33\"}', NULL, 1, '\n### Error updating database.  Cause: java.sql.SQLException: Data truncated for column \'difficulty\' at row 1\n### The error may exist in file [/Volumes/Suxia/IdeaProjects/RuoYi-Vue/ruoyi-psyc/target/classes/mapper/psyc/PsycTestMapper.xml]\n### The error may involve defaultParameterMap\n### The error occurred while setting parameters\n### SQL: insert into psyc_questions( id, content, type, test_id, difficulty, analysis, source, created_by, created_at, updated_at, deleted_at) values                        ( ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n### Cause: java.sql.SQLException: Data truncated for column \'difficulty\' at row 1\n; Data truncated for column \'difficulty\' at row 1; nested exception is java.sql.SQLException: Data truncated for column \'difficulty\' at row 1', '2025-10-24 14:05:41', 7463);
