mlType\":\"textarea\",\"increment\":false,\"insert\":true,\"isEdit\":\"1\",\"isIncrement\":\"0\",\"isInsert\":\"1\",\"isList\":\"1\",\"isPk\":\"0\",\"isQuery\":\"1\",\"isRequired\":\"0\",\"javaField\":\"description\",\"javaType\":\"String\",\"list\":true,\"params\":{},\"pk\":false,\"query\":true,\"queryType\":\"EQ\",\"required\":false,\"sort\":3,\"superColumn\":false,\"tableId\":1,\"updateBy\":\"\",\"updateTime\":\"2025-10-23 09:03:42\",\"usableColumn\":false},{\"capJavaField\":\"Status\",\"columnComment\":\"状态：0停用 1启用\",\"columnId\":4,\"columnName\":\"status\",\"columnType\":\"tinyint\",\"createBy\":\"admin\",\"createTime\":\"2025-10-22 08:46:42\",\"dictType\":\"\",\"edit\":true,\"htmlType\":\"radio\",\"increment\":false,\"insert\":true,\"isEdit', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-10-28 01:52:38', 277);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (123, '创建表', 0, 'com.ruoyi.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"sql\":\"CREATE TABLE psyc_assessment_rule (\\n  id BIGINT PRIMARY PRIMARY KEY AUTO_INCREMENT COMMENT \'规则ID\',\\n  test_id BIGINT NOT NULL COMMENT \'测评ID，关联测评主表\',\\n  min_score DECIMAL(8,2) NOT NULL COMMENT \'区间下限（含），如：50.00\',\\n  max_score DECIMAL(8,2) NOT NULL COMMENT \'区间上限（含），如：100.00\',\\n  level VARCHAR(200) NOT NULL COMMENT \'等级名称，如：优秀、良好、一般\',\\n  suggestion TEXT COMMENT \'建议文案，针对该等级的指导建议\',\\n  reference_result TEXT COMMENT \'参考结果，该等级对应的典型特征、案例说明等补充信息\',\\n  priority INT DEFAULT 0 COMMENT \'优先级，值越大优先匹配（当区间重叠时生效）\',\\n  is_deleted TINYINT NOT NULL DEFAULT 0 COMMENT \'是否删除：0-未删除，1-已删除\',\\n  FOREIGN KEY (test_id) REFERENCES assessment(id) ON DELETE CASCADE\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'测评动态评分区间规则表\';\"}', '{\"msg\":\"创建表结构异常\",\"code\":500}', 0, NULL, '2025-10-28 02:06:42', 5932);
