INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (128, '创建表', 0, 'com.ruoyi.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"sql\":\"CREATE TABLE psyc_assessment_rule (\\n  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT \'规则ID\',\\n  test_id BIGINT NOT NULL COMMENT \'测评ID，关联测评主表\',\\n  min_score DECIMAL(8,2) NOT NULL COMMENT \'区间下限（含），如：50.00\',\\n  max_score DECIMAL(8,2) NOT NULL COMMENT \'区间上限（含），如：100.00\',\\n  level VARCHAR(200) NOT NULL COMMENT \'等级名称，如：优秀、良好、一般\',\\n  suggestion TEXT COMMENT \'建议文案，针对该等级的指导建议\',\\n  reference_result TEXT COMMENT \'参考结果，该等级对应的典型特征、案例说明等补充信息\',\\n  priority INT DEFAULT 0 COMMENT \'优先级，值越大优先匹配（当区间重叠时生效）\',\\n  is_deleted TINYINT NOT NULL DEFAULT 0 COMMENT \'是否删除：0-未删除，1-已删除\',\\n  FOREIGN KEY (test_id) REFERENCES psyc_test(id) ON DELETE CASCADE,\\n  -- 普通索引：针对高频查询字段创建\\n  INDEX idx_test_id (test_id), -- 按测评ID查询规则（最常用，必加）\\n  INDEX idx_is_deleted (is_deleted) -- 过滤未删除数据（配合其他条件使用）\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'测评动态评分区间规则表\';\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-10-28 02:14:25', 366);
