INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (130, '代码生成', 2, 'com.ruoyi.generator.controller.GenController.editSave()', 'PUT', 1, 'admin', '研发部门', '/tool/gen', '127.0.0.1', '内网IP', '{\"businessName\":\"test\",\"className\":\"PsycTest\",\"columns\":[{\"capJavaField\":\"Id\",\"columnComment\":\"测评项目ID\",\"columnId\":1,\"columnName\":\"id\",\"columnType\":\"bigint\",\"createBy\":\"admin\",\"createTime\":\"2025-10-22 08:46:42\",\"dictType\":\"\",\"edit\":false,\"htmlType\":\"input\",\"increment\":true,\"insert\":true,\"isIncrement\":\"1\",\"isInsert\":\"1\",\"isPk\":\"1\",\"isRequired\":\"0\",\"javaField\":\"id\",\"javaType\":\"Long\",\"list\":false,\"params\":{},\"pk\":true,\"query\":false,\"queryType\":\"EQ\",\"required\":false,\"sort\":1,\"superColumn\":false,\"tableId\":1,\"updateBy\":\"\",\"updateTime\":\"2025-10-28 02:14:44\",\"usableColumn\":false},{\"capJavaField\":\"TestName\",\"columnComment\":\"测评项目名称\",\"columnId\":2,\"columnName\":\"test_name\",\"columnType\":\"varchar(100)\",\"createBy\":\"admin\",\"createTime\":\"2025-10-22 08:46:42\",\"dictType\":\"\",\"edit\":true,\"htmlType\":\"input\",\"increment\":false,\"insert\":true,\"isEdit\":\"1\",\"isIncrement\":\"0\",\"isInsert\":\"1\",\"isList\":\"1\",\"isPk\":\"0\",\"isQuery\":\"1\",\"isRequired\":\"1\",\"javaField\":\"testName\",\"javaType\":\"String\",\"list\":true,\"params\":{},\"pk\":false,\"query\":true,\"queryType\":\"LIKE\",\"required\":true,\"sort\":2,\"superColumn\":false,\"tableId\":1,\"updateBy\":\"\",\"updateTime\":\"2025-10-28 02:14:44\",\"usableColumn\":false},{\"capJavaField\":\"Description\",\"columnComment\":\"测评简介\",\"columnId\":3,\"columnName\":\"description\",\"columnType\":\"text\",\"createBy\":\"admin\",\"createTime\":\"2025-10-22 08:46:42\",\"dictType\":\"\",\"edit\":true,\"htmlType\":\"textarea\",\"increment\":false,\"insert\":true,\"isEdit\":\"1\",\"isIncrement\":\"0\",\"isInsert\":\"1\",\"isList\":\"1\",\"isPk\":\"0\",\"isQuery\":\"1\",\"isRequired\":\"0\",\"javaField\":\"description\",\"javaType\":\"String\",\"list\":true,\"params\":{},\"pk\":false,\"query\":true,\"queryType\":\"EQ\",\"required\":false,\"sort\":3,\"superColumn\":false,\"tableId\":1,\"updateBy\":\"\",\"updateTime\":\"2025-10-28 02:14:44\",\"usableColumn\":false},{\"capJavaField\":\"Status\",\"columnComment\":\"状态：0停用 1启用\",\"columnId\":4,\"columnName\":\"status\",\"columnType\":\"tinyint\",\"createBy\":\"admin\",\"createTime\":\"2025-10-22 08:46:42\",\"dictType\":\"\",\"edit\":true,\"htmlType\":\"radio\",\"increment\":false,\"insert\":true,\"is', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-10-28 02:15:53', 92);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (131, '代码生成', 8, 'com.ruoyi.generator.controller.GenController.batchGenCode()', 'GET', 1, 'admin', '研发部门', '/tool/gen/batchGenCode', '127.0.0.1', '内网IP', '{\"tables\":\"psyc_test\"}', NULL, 0, NULL, '2025-10-28 02:16:56', 118);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (132, '心理测评', 2, 'com.ruoyi.psyc.controller.PsycTestController.edit()', 'PUT', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-10-23 13:37:27\",\"description\":\"自我接纳指的是一个人对自己的特点、弱点、错误、无能和不足等方面的认知和接受程度。自我接受度越高，个体则越有可能体验到正向情绪如幸福、满足、自尊等，同时也更有可能建立起稳定和良好的关系。自我接纳问卷（The Self Acceptance Questionnaire，SAQ）由国内学者丛中等人于1999年开发，包括自我评价和自我接纳两个维度，用于反应个体的自我接纳水平。\",\"duration\":2,\"id\":1,\"params\":{},\"psycAssessmentRuleList\":[{\"isDeleted\":0,\"level\":\"自我接纳水平低\",\"maxScore\":32,\"minScore\":0,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度较低，存在着自我否定和自我压抑的情绪或认知状态，可能会出现以下表现：  （1）比如习惯性自我贬低，认为自己价值不足，无法获得他人的喜欢或认可；  （2）经常因为对自我不满意或因他人的评价而感到沮丧、焦虑、无助等负面情绪；  （3）人际关系上可能因为自我否定和离群感而导致拒绝或回避与他人沟通和交流，或者刻意去讨好他人而牺牲自己的利益；  （4）习惯性与其他人进行比较，尤其当比较的对象比较优秀时，会加大自卑的心理等。\",\"suggestion\":\"一方面可以尝试通过寻求心理辅导或咨询来了解自己的认知和情感状态，你可能认为自己没有价值或者无法获得他人的喜爱或认可，这是非常负面的自我评价，通过心理咨询可以帮助你学会认可自己的优点和遗憾，并且精进自己的沟通技能、正向思考或积极情绪调节，以进一步提高自我接纳程度；  另一方面，也可以进行减轻负面情绪和增强积极情绪的练习，比如舒缓的音乐、放松训练、冥想等，也可以帮助个体缓解焦虑和抑郁等负面情绪。\",\"testId\":1}],\"status\":1,\"testName\":\"自我接纳问卷\",\"totalQuestions\":16,\"updateTime\":\"2025-10-28 10:52:01\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-10-28 02:52:02', 292);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (133, '心理测评', 2, 'com.ruoyi.psyc.controller.PsycTestController.edit()', 'PUT', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-10-23 13:37:27\",\"description\":\"自我接纳指的是一个人对自己的特点、弱点、错误、无能和不足等方面的认知和接受程度。自我接受度越高，个体则越有可能体验到正向情绪如幸福、满足、自尊等，同时也更有可能建立起稳定和良好的关系。自我接纳问卷（The Self Acceptance Questionnaire，SAQ）由国内学者丛中等人于1999年开发，包括自我评价和自我接纳两个维度，用于反应个体的自我接纳水平。\",\"duration\":2,\"id\":1,\"params\":{},\"psycAssessmentRuleList\":[{\"id\":1,\"isDeleted\":0,\"level\":\"自我接纳水平低\",\"maxScore\":32,\"minScore\":0,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度较低，存在着自我否定和自我压抑的情绪或认知状态，可能会出现以下表现：  （1）比如习惯性自我贬低，认为自己价值不足，无法获得他人的喜欢或认可；  （2）经常因为对自我不满意或因他人的评价而感到沮丧、焦虑、无助等负面情绪；  （3）人际关系上可能因为自我否定和离群感而导致拒绝或回避与他人沟通和交流，或者刻意去讨好他人而牺牲自己的利益；  （4）习惯性与其他人进行比较，尤其当比较的对象比较优秀时，会加大自卑的心理等。\",\"suggestion\":\"一方面可以尝试通过寻求心理辅导或咨询来了解自己的认知和情感状态，你可能认为自己没有价值或者无法获得他人的喜爱或认可，这是非常负面的自我评价，通过心理咨询可以帮助你学会认可自己的优点和遗憾，并且精进自己的沟通技能、正向思考或积极情绪调节，以进一步提高自我接纳程度；  另一方面，也可以进行减轻负面情绪和增强积极情绪的练习，比如舒缓的音乐、放松训练、冥想等，也可以帮助个体缓解焦虑和抑郁等负面情绪。\",\"testId\":1},{\"isDeleted\":0,\"level\":\"自我接纳水平中等\",\"maxScore\":48,\"minScore\":33,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度相对稳定，但仍存在一些自我评价不高的情况；  你对自己的特质总体上持肯定的态度，也可以接纳某些缺陷和不足，但是同时有时候也可能会过于关注自己的缺陷和不足，而忽视了自己的优点和长处；  你认为自己跟大多数人一样，并不特别优秀，但也不特别差劲，但是你也可以接纳目前的状况等。\",\"suggestion\":\"可以深入探索自己的自我认知和自我评价，以提高自我接纳程度和心理健康水平，你可能意识到自己存在一些不足之处，但同时也有一些优点和潜力需要挖掘和发展，通过关注自己的兴趣、品牌、能力、心理需求等方面，进一步推进自我成长和发展。\",\"testId\":1}],\"status\":1,\"testName\":\"自我接纳问卷\",\"totalQuestions\":16,\"updateTime\":\"2025-10-28 10:55:03\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-10-28 02:55:04', 306);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (134, '心理测评', 2, 'com.ruoyi.psyc.controller.PsycTestController.edit()', 'PUT', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-10-23 13:37:27\",\"description\":\"自我接纳指的是一个人对自己的特点、弱点、错误、无能和不足等方面的认知和接受程度。自我接受度越高，个体则越有可能体验到正向情绪如幸福、满足、自尊等，同时也更有可能建立起稳定和良好的关系。自我接纳问卷（The Self Acceptance Questionnaire，SAQ）由国内学者丛中等人于1999年开发，包括自我评价和自我接纳两个维度，用于反应个体的自我接纳水平。\",\"duration\":2,\"id\":1,\"params\":{},\"psycAssessmentRuleList\":[{\"id\":1,\"isDeleted\":0,\"level\":\"自我接纳水平低\",\"maxScore\":32,\"minScore\":0,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度较低，存在着自我否定和自我压抑的情绪或认知状态，可能会出现以下表现：  （1）比如习惯性自我贬低，认为自己价值不足，无法获得他人的喜欢或认可；  （2）经常因为对自我不满意或因他人的评价而感到沮丧、焦虑、无助等负面情绪；  （3）人际关系上可能因为自我否定和离群感而导致拒绝或回避与他人沟通和交流，或者刻意去讨好他人而牺牲自己的利益；  （4）习惯性与其他人进行比较，尤其当比较的对象比较优秀时，会加大自卑的心理等。\",\"suggestion\":\"一方面可以尝试通过寻求心理辅导或咨询来了解自己的认知和情感状态，你可能认为自己没有价值或者无法获得他人的喜爱或认可，这是非常负面的自我评价，通过心理咨询可以帮助你学会认可自己的优点和遗憾，并且精进自己的沟通技能、正向思考或积极情绪调节，以进一步提高自我接纳程度；  另一方面，也可以进行减轻负面情绪和增强积极情绪的练习，比如舒缓的音乐、放松训练、冥想等，也可以帮助个体缓解焦虑和抑郁等负面情绪。\",\"testId\":1},{\"id\":2,\"isDeleted\":0,\"level\":\"自我接纳水平中等\",\"maxScore\":48,\"minScore\":33,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度相对稳定，但仍存在一些自我评价不高的情况；  你对自己的特质总体上持肯定的态度，也可以接纳某些缺陷和不足，但是同时有时候也可能会过于关注自己的缺陷和不足，而忽视了自己的优点和长处；  你认为自己跟大多数人一样，并不特别优秀，但也不特别差劲，但是你也可以接纳目前的状况等。\",\"suggestion\":\"可以深入探索自己的自我认知和自我评价，以提高自我接纳程度和心理健康水平，你可能意识到自己存在一些不足之处，但同时也有一些优点和潜力需要挖掘和发展，通过关注自己的兴趣、品牌、能力、心理需求等方面，进一步推进自我成长和发展。\",\"testId\":1},{\"isDeleted\":0,\"level\":\"自我接纳水平高\",\"maxScore\":64,\"minScore\":49,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度非常高，能够很好地认识和接受自己的弱点和不足，并具备灵活应对生活问题和挑战的能力；  相信自己能够在生活中克服困难和挑战，在工作和学习中达到较高水平；  面对成功和失败都具有稳定的情感体验，不会陷入过度情感激动或抑郁症状态；  具备较好的人际互动能力，容易与他人建立联系和沟通，尊重他人的观点和需求；  懂得如何解决自己和他人的问题，以积极健康的方式表达自己的意见和想法等。\",\"suggestion\":\"继续保持良好自我接纳的状态，同时也可以进一步探索和发展自己的潜力，成为更好的自己。  比如挑战自己的舒适区、开展新的兴趣和技能、寻求更高层次的工作或学习机会等，以增强自信心和认同感等。\",\"testId\":1}],\"status\":1,\"testName\":\"自我接纳问卷\",\"totalQuestions\":16,\"updateTime\":\"2025-10-28 10:55:50\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-10-28 02:55:50', 91);
