INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (146, '创建表', 0, 'com.ruoyi.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"sql\":\"-- 动态主表\\nCREATE TABLE `psyc_post` (\\n  `id` BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT \'动态ID\',\\n  `user_id` BIGINT NOT NULL COMMENT \'发布用户ID\',\\n  `content` TEXT COMMENT \'文字内容\',\\n  `visible` TINYINT DEFAULT 1 COMMENT \'可见范围(1公开,2仅好友,3私密)\',\\n  `like_count` INT DEFAULT 0 COMMENT \'点赞数\',\\n  `comment_count` INT DEFAULT 0 COMMENT \'评论数\',\\n  `favorite_count` INT DEFAULT 0 COMMENT \'收藏数\',\\n  `share_count` INT DEFAULT 0 COMMENT \'分享数\',\\n  `status` TINYINT DEFAULT 1 COMMENT \'状态(1正常,0删除,2审核中)\',\\n  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT \'发布时间\',\\n  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\',\\n  INDEX `idx_user_id` (`user_id`),\\n  INDEX `idx_created_at` (`created_at`)\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'动态主表\';\\n\\n-- 动态媒体资源表（图片/视频）\\nCREATE TABLE `psyc_post_media` (\\n  `id` BIGINT PRIMARY KEY AUTO_INCREMENT,\\n  `post_id` BIGINT NOT NULL COMMENT \'动态ID\',\\n  `media_url` VARCHAR(255) NOT NULL COMMENT \'媒体URL\',\\n  `media_type` TINYINT DEFAULT 1 COMMENT \'类型(1图片,2视频)\',\\n  `sort_order` INT DEFAULT 0 COMMENT \'顺序\',\\n  INDEX `idx_post_id` (`post_id`)\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'动态媒体资源表\';\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-10-30 03:21:26', 4703);
