INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (174, '通知公告', 2, 'com.xinling.web.controller.system.SysNoticeController.edit()', 'PUT', 1, 'admin', '研发部门', '/system/notice', '127.0.0.1', '内网IP', '{\"createBy\":\"admin\",\"createTime\":\"2025-10-20 06:46:10\",\"noticeContent\":\"<p>为保障系统稳定运行，我们将于 <strong>2025 年 10 月 20 日凌晨</strong> 对 <strong>心灵系统</strong> 进行维护。在此期间，可能会出现短暂无法访问的情况。</p><p><br></p><p>维护完成后，系统将正常恢复使用。</p><p>感谢您的理解与支持！</p>\",\"noticeId\":2,\"noticeTitle\":\"维护通知：2025-10-20 心灵系统凌晨维护\",\"noticeType\":\"1\",\"params\":{},\"remark\":\"管理员\",\"status\":\"0\",\"updateBy\":\"admin\",\"updateTime\":\"2025-11-06 08:18:20\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-11-19 03:14:43', 40);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (175, '创建表', 0, 'com.xinling.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"sql\":\"CREATE TABLE psyc_feedback (\\n    id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT \'主键ID\',\\n    user_id BIGINT NOT NULL COMMENT \'提交反馈的用户ID\',\\n    type TINYINT NOT NULL COMMENT \'反馈类型：1-Bug问题 2-产品建议 3-投诉 4-功能需求 5-其他\',\\n    content TEXT NOT NULL COMMENT \'反馈内容（用户填写的文本描述）\',\\n    images JSON DEFAULT NULL COMMENT \'截图/图片列表，JSON数组形式\',\\n    contact VARCHAR(100) DEFAULT NULL COMMENT \'用户联系方式（手机号/邮箱）\',\\n    device_info JSON DEFAULT NULL COMMENT \'自动收集的设备信息（系统、型号、APP版本等）\',\\n    status TINYINT NOT NULL DEFAULT 0 COMMENT \'处理状态：0-待处理 1-处理中 2-已处理 3-已关闭\',\\n    create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT \'创建时间（提交时间）\',\\n    update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\',\\n\\n    INDEX idx_user(user_id) COMMENT \'用户ID索引（用于查询某用户的反馈）\',\\n    INDEX idx_status(status) COMMENT \'状态索引（用于后台筛选状态）\'\\n) COMMENT=\'用户意见反馈主表\';\\n\\nCREATE TABLE psyc_feedback_reply (\\n    id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT \'回复记录主键ID\',\\n    feedback_id BIGINT NOT NULL COMMENT \'关联的反馈ID（外键）\',\\n    reply_user_id BIGINT NOT NULL COMMENT \'回复的管理员ID\',\\n    content TEXT NOT NULL COMMENT \'回复内容\',\\n    create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT \'回复时间\',\\n\\n    FOREIGN KEY (feedback_id) REFERENCES psyc_feedback(id)\\n) COMMENT=\'意见反馈的回复记录表\';\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-11-19 09:26:35', 4297);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (176, '代码生成', 2, 'com.xinling.generator.controller.GenController.editSave()', 'PUT', 1, 'admin', '研发部门', '/tool/gen', '127.0.0.1', '内网IP', '{\"businessName\":\"feedback\",\"className\":\"PsycFeedback\",\"columns\":[{\"capJavaField\":\"Id\",\"columnComment\":\"主键ID\",\"columnId\":59,\"columnName\":\"id\",\"columnType\":\"bigint\",\"createBy\":\"admin\",\"createTime\":\"2025-11-19 09:26:35\",\"dictType\":\"\",\"edit\":false,\"htmlType\":\"input\",\"increment\":true,\"insert\":true,\"isIncrement\":\"1\",\"isInsert\":\"1\",\"isPk\":\"1\",\"isRequired\":\"0\",\"javaField\":\"id\",\"javaType\":\"Long\",\"list\":false,\"params\":{},\"pk\":true,\"query\":false,\"queryType\":\"EQ\",\"required\":false,\"sort\":1,\"superColumn\":false,\"tableId\":8,\"updateBy\":\"\",\"usableColumn\":false},{\"capJavaField\":\"UserId\",\"columnComment\":\"提交反馈的用户ID\",\"columnId\":60,\"columnName\":\"user_id\",\"columnType\":\"bigint\",\"createBy\":\"admin\",\"createTime\":\"2025-11-19 09:26:35\",\"dictType\":\"\",\"edit\":true,\"htmlType\":\"input\",\"increment\":false,\"insert\":true,\"isEdit\":\"1\",\"isIncrement\":\"0\",\"isInsert\":\"1\",\"isList\":\"1\",\"isPk\":\"0\",\"isQuery\":\"1\",\"isRequired\":\"1\",\"javaField\":\"userId\",\"javaType\":\"Long\",\"list\":true,\"params\":{},\"pk\":false,\"query\":true,\"queryType\":\"EQ\",\"required\":true,\"sort\":2,\"superColumn\":false,\"tableId\":8,\"updateBy\":\"\",\"usableColumn\":false},{\"capJavaField\":\"Type\",\"columnComment\":\"反馈类型：1-Bug问题 2-产品建议 3-投诉 4-功能需求 5-其他\",\"columnId\":61,\"columnName\":\"type\",\"columnType\":\"tinyint\",\"createBy\":\"admin\",\"createTime\":\"2025-11-19 09:26:35\",\"dictType\":\"\",\"edit\":true,\"htmlType\":\"select\",\"increment\":false,\"insert\":true,\"isEdit\":\"1\",\"isIncrement\":\"0\",\"isInsert\":\"1\",\"isList\":\"1\",\"isPk\":\"0\",\"isQuery\":\"1\",\"isRequired\":\"1\",\"javaField\":\"type\",\"javaType\":\"Long\",\"list\":true,\"params\":{},\"pk\":false,\"query\":true,\"queryType\":\"EQ\",\"required\":true,\"sort\":3,\"superColumn\":false,\"tableId\":8,\"updateBy\":\"\",\"usableColumn\":false},{\"capJavaField\":\"Content\",\"columnComment\":\"反馈内容（用户填写的文本描述）\",\"columnId\":62,\"columnName\":\"content\",\"columnType\":\"text\",\"createBy\":\"admin\",\"createTime\":\"2025-11-19 09:26:35\",\"dictType\":\"\",\"edit\":true,\"htmlType\":\"editor\",\"increment\":false,\"insert\":true,\"isEdit\":\"1\",\"isIncrement\":\"0\",\"isInsert\":\"1\",\"isList\":\"1\",\"isPk\":\"0\",\"isQuery\":\"1\",\"isRequired\":', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-11-19 09:27:46', 85);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (177, '心理测评', 2, 'com.xinling.web.controller.psyc.PsycTestController.edit()', 'PUT', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-10-23 13:37:27\",\"description\":\"自我接纳指的是一个人对自己的特点、弱点、错误、无能和不足等方面的认知和接受程度。自我接受度越高，个体则越有可能体验到正向情绪如幸福、满足、自尊等，同时也更有可能建立起稳定和良好的关系。自我接纳问卷（The Self Acceptance Questionnaire，SAQ）由国内学者丛中等人于1999年开发，包括自我评价和自我接纳两个维度，用于反应个体的自我接纳水平。\",\"duration\":2,\"id\":1,\"params\":{},\"psycAssessmentRuleList\":[{\"id\":1,\"isDeleted\":0,\"level\":\"自我接纳水平低\",\"maxScore\":32,\"minScore\":0,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度较低，存在着自我否定和自我压抑的情绪或认知状态，可能会出现以下表现：  （1）比如习惯性自我贬低，认为自己价值不足，无法获得他人的喜欢或认可；  （2）经常因为对自我不满意或因他人的评价而感到沮丧、焦虑、无助等负面情绪；  （3）人际关系上可能因为自我否定和离群感而导致拒绝或回避与他人沟通和交流，或者刻意去讨好他人而牺牲自己的利益；  （4）习惯性与其他人进行比较，尤其当比较的对象比较优秀时，会加大自卑的心理等。\",\"suggestion\":\"一方面可以尝试通过寻求心理辅导或咨询来了解自己的认知和情感状态，你可能认为自己没有价值或者无法获得他人的喜爱或认可，这是非常负面的自我评价，通过心理咨询可以帮助你学会认可自己的优点和遗憾，并且精进自己的沟通技能、正向思考或积极情绪调节，以进一步提高自我接纳程度；  另一方面，也可以进行减轻负面情绪和增强积极情绪的练习，比如舒缓的音乐、放松训练、冥想等，也可以帮助个体缓解焦虑和抑郁等负面情绪。\",\"testId\":1},{\"id\":2,\"isDeleted\":0,\"level\":\"自我接纳水平中等\",\"maxScore\":48,\"minScore\":33,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度相对稳定，但仍存在一些自我评价不高的情况；  你对自己的特质总体上持肯定的态度，也可以接纳某些缺陷和不足，但是同时有时候也可能会过于关注自己的缺陷和不足，而忽视了自己的优点和长处；  你认为自己跟大多数人一样，并不特别优秀，但也不特别差劲，但是你也可以接纳目前的状况等。\",\"suggestion\":\"可以深入探索自己的自我认知和自我评价，以提高自我接纳程度和心理健康水平，你可能意识到自己存在一些不足之处，但同时也有一些优点和潜力需要挖掘和发展，通过关注自己的兴趣、品牌、能力、心理需求等方面，进一步推进自我成长和发展。\",\"testId\":1},{\"id\":4,\"isDeleted\":0,\"level\":\"自我接纳水平高\",\"maxScore\":64,\"minScore\":49,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度非常高，能够很好地认识和接受自己的弱点和不足，并具备灵活应对生活问题和挑战的能力；  相信自己能够在生活中克服困难和挑战，在工作和学习中达到较高水平；  面对成功和失败都具有稳定的情感体验，不会陷入过度情感激动或抑郁症状态；  具备较好的人际互动能力，容易与他人建立联系和沟通，尊重他人的观点和需求；  懂得如何解决自己和他人的问题，以积极健康的方式表达自己的意见和想法等。\",\"suggestion\":\"继续保持良好自我接纳的状态，同时也可以进一步探索和发展自己的潜力，成为更好的自己。  比如挑战自己的舒适区、开展新的兴趣和技能、寻求更高层次的工作或学习机会等，以增强自信心和认同感等。\",\"testId\":1}],\"status\":0,\"testName\":\"自我接纳问卷\",\"totalQuestions\":16,\"updateTime\":\"2025-11-20 09:27:35\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-11-20 01:27:35', 123);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (178, '心理测评', 2, 'com.xinling.web.controller.psyc.PsycTestController.edit()', 'PUT', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-10-23 13:37:27\",\"description\":\"自我接纳指的是一个人对自己的特点、弱点、错误、无能和不足等方面的认知和接受程度。自我接受度越高，个体则越有可能体验到正向情绪如幸福、满足、自尊等，同时也更有可能建立起稳定和良好的关系。自我接纳问卷（The Self Acceptance Questionnaire，SAQ）由国内学者丛中等人于1999年开发，包括自我评价和自我接纳两个维度，用于反应个体的自我接纳水平。\",\"duration\":2,\"id\":1,\"params\":{},\"psycAssessmentRuleList\":[{\"id\":1,\"isDeleted\":0,\"level\":\"自我接纳水平低\",\"maxScore\":32,\"minScore\":0,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度较低，存在着自我否定和自我压抑的情绪或认知状态，可能会出现以下表现：  （1）比如习惯性自我贬低，认为自己价值不足，无法获得他人的喜欢或认可；  （2）经常因为对自我不满意或因他人的评价而感到沮丧、焦虑、无助等负面情绪；  （3）人际关系上可能因为自我否定和离群感而导致拒绝或回避与他人沟通和交流，或者刻意去讨好他人而牺牲自己的利益；  （4）习惯性与其他人进行比较，尤其当比较的对象比较优秀时，会加大自卑的心理等。\",\"suggestion\":\"一方面可以尝试通过寻求心理辅导或咨询来了解自己的认知和情感状态，你可能认为自己没有价值或者无法获得他人的喜爱或认可，这是非常负面的自我评价，通过心理咨询可以帮助你学会认可自己的优点和遗憾，并且精进自己的沟通技能、正向思考或积极情绪调节，以进一步提高自我接纳程度；  另一方面，也可以进行减轻负面情绪和增强积极情绪的练习，比如舒缓的音乐、放松训练、冥想等，也可以帮助个体缓解焦虑和抑郁等负面情绪。\",\"testId\":1},{\"id\":2,\"isDeleted\":0,\"level\":\"自我接纳水平中等\",\"maxScore\":48,\"minScore\":33,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度相对稳定，但仍存在一些自我评价不高的情况；  你对自己的特质总体上持肯定的态度，也可以接纳某些缺陷和不足，但是同时有时候也可能会过于关注自己的缺陷和不足，而忽视了自己的优点和长处；  你认为自己跟大多数人一样，并不特别优秀，但也不特别差劲，但是你也可以接纳目前的状况等。\",\"suggestion\":\"可以深入探索自己的自我认知和自我评价，以提高自我接纳程度和心理健康水平，你可能意识到自己存在一些不足之处，但同时也有一些优点和潜力需要挖掘和发展，通过关注自己的兴趣、品牌、能力、心理需求等方面，进一步推进自我成长和发展。\",\"testId\":1},{\"id\":4,\"isDeleted\":0,\"level\":\"自我接纳水平高\",\"maxScore\":64,\"minScore\":49,\"params\":{},\"priority\":0,\"referenceResult\":\"你的自我接纳程度非常高，能够很好地认识和接受自己的弱点和不足，并具备灵活应对生活问题和挑战的能力；  相信自己能够在生活中克服困难和挑战，在工作和学习中达到较高水平；  面对成功和失败都具有稳定的情感体验，不会陷入过度情感激动或抑郁症状态；  具备较好的人际互动能力，容易与他人建立联系和沟通，尊重他人的观点和需求；  懂得如何解决自己和他人的问题，以积极健康的方式表达自己的意见和想法等。\",\"suggestion\":\"继续保持良好自我接纳的状态，同时也可以进一步探索和发展自己的潜力，成为更好的自己。  比如挑战自己的舒适区、开展新的兴趣和技能、寻求更高层次的工作或学习机会等，以增强自信心和认同感等。\",\"testId\":1}],\"status\":1,\"testName\":\"自我接纳问卷\",\"totalQuestions\":16,\"updateTime\":\"2025-11-20 09:27:46\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-11-20 01:27:46', 63);
