INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (241, '动态管理', 2, 'com.xinling.web.controller.psyc.PsycPostController.edit()', 'PUT', 1, 'admin', '研发部门', '/psyc/post', '127.0.0.1', '内网IP', '{\"commentCount\":10086,\"content\":\"<p><strong>测试动态内容</strong></p>\",\"createdAt\":\"2025-10-30\",\"favoriteCount\":10086,\"id\":1,\"likeCount\":10086,\"params\":{},\"psycPostMediaList\":[{\"id\":1,\"mediaType\":1,\"mediaUrl\":\"https://i.pinimg.com/1200x/83/2f/ff/832fffb821e869cfe7acceb70cd75250.jpg\",\"params\":{},\"postId\":1,\"sortOrder\":1}],\"shareCount\":10086,\"status\":1,\"updatedAt\":\"2025-10-30\",\"userId\":10086,\"visible\":1}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-11-30 01:23:40', 141);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (242, '创建表', 0, 'com.xinling.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"sql\":\"CREATE TABLE `infra_file_config` (\\n  `id` bigint NOT NULL AUTO_INCREMENT COMMENT \'编号\',\\n  `name` varchar(63) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT \'配置名\',\\n  `storage` tinyint NOT NULL COMMENT \'存储器\',\\n  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'备注\',\\n  `master` bit(1) NOT NULL COMMENT \'是否为主配置\',\\n  `config` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT \'存储配置\',\\n  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT \'\' COMMENT \'创建者\',\\n  `deleted` bit(1) NOT NULL DEFAULT b\'0\' COMMENT \'是否删除\',\\n  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT \'创建时间\',\\n  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT \'\' COMMENT \'更新者\',\\n  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\',\\n  PRIMARY KEY (`id`) USING BTREE\\n) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT=\'文件配置表\';\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-11-30 02:49:42', 600);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (243, '菜单管理', 1, 'com.xinling.web.controller.system.SysMenuController.add()', 'POST', 1, 'admin', '研发部门', '/system/menu', '127.0.0.1', '内网IP', '{\"children\":[],\"createBy\":\"admin\",\"icon\":\"file\",\"isCache\":\"0\",\"isFrame\":\"1\",\"menuName\":\"文件管理\",\"menuType\":\"M\",\"orderNum\":4,\"params\":{},\"parentId\":3,\"path\":\"infra\",\"status\":\"0\",\"visible\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-02 06:51:12', 168);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (244, '通知公告', 1, 'com.xinling.web.controller.system.SysNoticeController.add()', 'POST', 1, 'admin', '研发部门', '/system/notice', '127.0.0.1', '内网IP', '{\"createBy\":\"admin\",\"noticeContent\":\"<p>Spring Boot到3.5以上版本的任务。以下是我所做的更改：</p><p>1. 升级了Spring Boot版本</p><p>将Spring Boot版本从3.2.5升级到3.5.4（在根pom.xml中）</p><p>2. 更新了相关依赖以兼容Spring Boot 3.5+</p><p>Spring Framework版本从6.1.6升级到6.1.15</p><p>Spring Security版本从6.2.5升级到6.3.5</p><p>Druid连接池版本从1.2.27升级到1.2.24</p><p>Logback版本从1.4.14升级到1.5.6</p><p>Tomcat版本从10.1.24升级到11.0.2</p><p>Maven编译器插件版本更新到3.13.0</p><p>SpringDoc版本从2.1.0升级到2.6.0</p><p>3. 更新了Redis配置</p><p>在application.yml中，保持了max-wait-time配置项（这是Spring Boot 3.x中的正确配置）</p><p>4. 修复了POM文件格式错误</p><p>修复了由于编辑过程中引入的多余字符导致的POM格式错误</p><p>5. 验证了项目构建</p><p>成功执行了mvn clean compile，所有模块都编译通过</p>\",\"noticeTitle\":\"温馨提醒：2026-01-07 心灵新版本发布啦\",\"noticeType\":\"1\",\"params\":{},\"status\":\"0\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-01-07 08:33:20', 109);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (245, '定时任务', 1, 'com.xinling.quartz.controller.SysJobController.add()', 'POST', 1, 'admin', '研发部门', '/monitor/job', '127.0.0.1', '内网IP', '{\"concurrent\":\"1\",\"createBy\":\"admin\",\"cronExpression\":\"0 0 2 * * ?\",\"invokeTarget\":\"chatHistoryCleanupTask.cleanupExpiredChatHistory()\",\"jobId\":100,\"jobName\":\"聊天历史记录清理任务\",\"misfirePolicy\":\"1\",\"nextValidTime\":\"2026-01-13 02:00:00\",\"params\":{},\"status\":\"1\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-01-12 06:18:30', 179);
