INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (284, '心理测评', 1, 'com.xinling.web.controller.psyc.PsycTestController.add()', 'POST', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2026-04-21 14:18:51\",\"description\":\"抑郁自评量表(Self-Rating Depression Scale， SDS)由W.K.Zung编制于1965年，为美国教育卫生福利部推荐的用于精神药理学研究的量表之一，SDS使用简便，能直观地反映病人抑郁的主观感受及其在治疗中的变化，广泛应用于门诊病人的粗筛、情绪状态评定以及调查科研等，适用于具有抑郁症状的成年人。\",\"duration\":2,\"id\":2,\"params\":{},\"psycAssessmentRuleList\":[],\"status\":1,\"testName\":\"抑郁自评量表\",\"totalQuestions\":20} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-21 06:18:51', 252);
