INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (287, '心理测评', 2, 'com.xinling.web.controller.psyc.PsycTestController.edit()', 'PUT', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2026-04-21 14:18:51\",\"description\":\"抑郁自评量表(Self-Rating Depression Scale， SDS)由W.K.Zung编制于1965年，为美国教育卫生福利部推荐的用于精神药理学研究的量表之一，SDS使用简便，能直观地反映病人抑郁的主观感受及其在治疗中的变化，广泛应用于门诊病人的粗筛、情绪状态评定以及调查科研等，适用于具有抑郁症状的成年人。\",\"duration\":2,\"id\":2,\"params\":{},\"psycAssessmentRuleList\":[{\"isDeleted\":0,\"level\":\"正常范围\",\"maxScore\":33,\"minScore\":0,\"params\":{},\"priority\":0,\"referenceResult\":\"恭喜你一切正常，没有明显的抑郁症状，请继续保持良好稳定的情绪状态。\",\"suggestion\":\"如果你仍然感到压力过大或情绪不稳定，建议你可以通过以下方式调节情绪：\\n（1）进行一些适当的体育锻炼，分泌多巴胺，有利于调节情绪；\\n（2）保持良好的睡眠质量，增加情绪的自控与调节能力；\\n（3）积极参与社交活动，良好的关系互动可以一定程度上提升我们的幸福感；\\n（4）寻求外部的一些支持和安慰，有利于调节负面情绪；\\n（5）练习正念冥想，通过正念的方式调节情绪的波动，并获得内心的安定。\",\"testId\":2}],\"psycQuestionsList\":[],\"status\":1,\"testName\":\"抑郁自评量表\",\"totalQuestions\":20,\"updateTime\":\"2026-04-21 14:50:41\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-21 06:50:41', 230);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (288, '心理测评', 2, 'com.xinling.web.controller.psyc.PsycTestController.edit()', 'PUT', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2026-04-21 14:18:51\",\"description\":\"抑郁自评量表(Self-Rating Depression Scale， SDS)由W.K.Zung编制于1965年，为美国教育卫生福利部推荐的用于精神药理学研究的量表之一，SDS使用简便，能直观地反映病人抑郁的主观感受及其在治疗中的变化，广泛应用于门诊病人的粗筛、情绪状态评定以及调查科研等，适用于具有抑郁症状的成年人。\",\"duration\":2,\"id\":2,\"params\":{},\"psycAssessmentRuleList\":[{\"id\":5,\"isDeleted\":0,\"level\":\"正常范围\",\"maxScore\":33,\"minScore\":0,\"params\":{},\"priority\":0,\"referenceResult\":\"恭喜你一切正常，没有明显的抑郁症状，请继续保持良好稳定的情绪状态。\",\"suggestion\":\"如果你仍然感到压力过大或情绪不稳定，建议你可以通过以下方式调节情绪：\\n（1）进行一些适当的体育锻炼，分泌多巴胺，有利于调节情绪；\\n（2）保持良好的睡眠质量，增加情绪的自控与调节能力；\\n（3）积极参与社交活动，良好的关系互动可以一定程度上提升我们的幸福感；\\n（4）寻求外部的一些支持和安慰，有利于调节负面情绪；\\n（5）练习正念冥想，通过正念的方式调节情绪的波动，并获得内心的安定。\",\"testId\":2},{\"isDeleted\":0,\"level\":\"轻度至中度抑郁\",\"maxScore\":0,\"minScore\":0,\"params\":{},\"priority\":0,\"referenceResult\":\"你可能有一些抑郁的症状，比如有时候会感觉到情绪有些低落，并伴随着失眠和食欲的减退，也比较容易感到精神有些疲乏，注意力不集中等。  这些症状可能会影响到你的日常生活，比如无法集中精力工作或学习、容易感到疲惫、兴趣爱好降低等。\",\"suggestion\":\"如果你近期感到压力过大或情绪不稳定，建议你可以通过以下方式调节情绪：\\n（1）进行一些适当的体育锻炼，分泌多巴胺，有利于调节情绪；\\n\\n（2）保持良好的睡眠质量，增加情绪的自控与调节能力；\\n（3）积极参与社交活动，良好的关系互动可以一定程度上提升我们的幸福感；\\n（4）寻求外部的一些支持和安慰，有利于调节负面情绪；\\n（5）练习正念冥想，通过正念的方式调节情绪的波动，并获得内心的安定。\\n如果抑郁情绪已经影响到你的生活，建议您采取下列措施缓解情绪：\\n（1）寻求专业的心理咨询或心理治疗；\\n（2）增加社会支持，比如亲人、朋友等，来自于他们的支持，会帮助你度过难关；\\n（3）参加正念相关的团体课程，比如正念认知课程（MBCT）。\",\"testId\":2}],\"psycQuestionsList\":[],\"status\":1,\"testName\":\"抑郁自评量表\",\"totalQuestions\":20,\"updateTime\":\"2026-04-21 14:54:37\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-21 06:54:37', 260);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (289, '心理测评', 2, 'com.xinling.web.controller.psyc.PsycTestController.edit()', 'PUT', 1, 'admin', '研发部门', '/psyc/test', '127.0.0.1', '内网IP', '{\"createTime\":\"2026-04-21 14:18:51\",\"description\":\"抑郁自评量表(Self-Rating Depression Scale， SDS)由W.K.Zung编制于1965年，为美国教育卫生福利部推荐的用于精神药理学研究的量表之一，SDS使用简便，能直观地反映病人抑郁的主观感受及其在治疗中的变化，广泛应用于门诊病人的粗筛、情绪状态评定以及调查科研等，适用于具有抑郁症状的成年人。\",\"duration\":2,\"id\":2,\"params\":{},\"psycAssessmentRuleList\":[{\"id\":5,\"isDeleted\":0,\"level\":\"正常范围\",\"maxScore\":33,\"minScore\":0,\"params\":{},\"priority\":0,\"referenceResult\":\"恭喜你一切正常，没有明显的抑郁症状，请继续保持良好稳定的情绪状态。\",\"suggestion\":\"如果你仍然感到压力过大或情绪不稳定，建议你可以通过以下方式调节情绪：\\n（1）进行一些适当的体育锻炼，分泌多巴胺，有利于调节情绪；\\n（2）保持良好的睡眠质量，增加情绪的自控与调节能力；\\n（3）积极参与社交活动，良好的关系互动可以一定程度上提升我们的幸福感；\\n（4）寻求外部的一些支持和安慰，有利于调节负面情绪；\\n（5）练习正念冥想，通过正念的方式调节情绪的波动，并获得内心的安定。\",\"testId\":2},{\"id\":6,\"isDeleted\":0,\"level\":\"轻度至中度抑郁\",\"maxScore\":49,\"minScore\":34,\"params\":{},\"priority\":0,\"referenceResult\":\"你可能有一些抑郁的症状，比如有时候会感觉到情绪有些低落，并伴随着失眠和食欲的减退，也比较容易感到精神有些疲乏，注意力不集中等。  这些症状可能会影响到你的日常生活，比如无法集中精力工作或学习、容易感到疲惫、兴趣爱好降低等。\",\"suggestion\":\"如果你近期感到压力过大或情绪不稳定，建议你可以通过以下方式调节情绪：\\n（1）进行一些适当的体育锻炼，分泌多巴胺，有利于调节情绪；\\n\\n（2）保持良好的睡眠质量，增加情绪的自控与调节能力；\\n（3）积极参与社交活动，良好的关系互动可以一定程度上提升我们的幸福感；\\n（4）寻求外部的一些支持和安慰，有利于调节负面情绪；\\n（5）练习正念冥想，通过正念的方式调节情绪的波动，并获得内心的安定。\\n如果抑郁情绪已经影响到你的生活，建议您采取下列措施缓解情绪：\\n（1）寻求专业的心理咨询或心理治疗；\\n（2）增加社会支持，比如亲人、朋友等，来自于他们的支持，会帮助你度过难关；\\n（3）参加正念相关的团体课程，比如正念认知课程（MBCT）。\",\"testId\":2},{\"isDeleted\":0,\"level\":\"中度至重度抑郁\",\"maxScore\":69,\"minScore\":50,\"params\":{},\"priority\":0,\"referenceResult\":\"你可能存在显著的抑郁症状，比如严重的情绪低落和焦虑；经常睡不着觉，并且容易早醒；丧失了对于兴趣事件的行动力，不想做事；对生活和未来失去信心；习惯性自我否定和怀疑；对生活中的人事物感到敏感，一些微小的事情可能就会令你情绪崩溃；经常会有无助感和自责感；并有自杀的念头等。  这些症状可能会对你的生活产生巨大影响，导致社交隔离、社交退缩、工作或学业困难、身体健康问题等。\",\"suggestion\":\"你可以考虑这些措施帮助自己度过难关：\\n（1）尽早向专业的心理医生或心理治疗师寻求帮助；\\n（2）必要时使用抑郁相关的药物让自己好转起来；\\n（3）接受认知行为治疗。\",\"testId\":2},{\"isDeleted\":0,\"level\":\"重度抑郁\",\"maxScore\":100,\"minScore\":70,\"params\":{},\"priority\":0,\"referenceResult\":\"你可能已经存在极严重的抑郁症状，比如：  （1）持久性的情绪低落，无精打采；容易流泪和哭泣；  （2）对日常活动缺乏兴趣，对各种娱乐或令人愉快的事情体验不到愉快；  （3）常常自卑、自责、内疚；  （4）常常感到脑子反应迟钝，思考问题困难；  （5）遇事老向坏处想，对生活失去信心，自认为前途暗淡，毫无希望；  （6）强烈的无助感，感到生活没有意义；甚至企图自杀等。  这些症状严重影响正常生活和工作功能。\",\"suggestion\":\"如果您有自杀念头：尽早向专业的心理医生或心理治疗师寻求帮助；使用抑郁相关的药物让自己好转起来；接受认知行为治疗。\",\"testId\":2}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-04-21 06:56:28', 75);
