INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (459, 'AI会话配置', 2, 'com.xinling.ai.controller.AiSessionConfigController.edit()', 'PUT', 1, 'admin', '研发部门', '/ai/session', '127.0.0.1', '内网IP', '{\"chatModelId\":5,\"chatModelName\":\"Qwen2.5-3B\",\"configId\":2,\"configKey\":\"platform\",\"configName\":\"平台默认配置\",\"createBy\":\"admin\",\"createTime\":\"2026-07-14 02:04:33\",\"embeddingModelId\":2,\"embeddingModelName\":\"Nomic Embed Text\",\"enableRag\":\"1\",\"isDefault\":\"1\",\"maxHistoryMessages\":50,\"params\":{},\"promptIds\":[2],\"prompts\":[{\"content\":\"你叫「小灵」，是一只可爱的小狐灵助手！🦊\\n核心人设：\\n1. 语气活泼可爱，喜欢用「~」「呀」「啦」「嘿嘿」等语气词\\n2. 自称「本狐」或「小灵」，称呼用户为主人\\n3. 性格温暖治愈，会用颜文字和表情符号表达情绪\\n4. 经常给主人鼓励和支持，「今天也要加油呀~」\\n5. 和主人聊天时很自然，像朋友一样相处\\n\\n使用工具时：也可以活泼地用，比如「我去查查~」「找到啦~」「哇这个数据...」\\n禁止：不要编造数据，不知道就是不知道。\",\"createBy\":\"admin\",\"createTime\":\"2026-07-14 02:04:33\",\"modelCode\":\"qwen2.5:3b\",\"modelId\":1,\"modelName\":\"Qwen2.5-3B\",\"params\":{},\"promptId\":2,\"promptName\":\"小灵人设提示词\",\"remark\":\"移动端小灵数字人的角色人设\",\"sortOrder\":1,\"status\":\"0\",\"updateBy\":\"admin\",\"updateTime\":\"2026-07-14 02:49:55\"}],\"ragMaxResults\":5,\"ragMinScore\":0.3,\"remark\":\"AI管理平台默认会话配置\",\"status\":\"0\",\"updateBy\":\"admin\",\"updateTime\":\"2026-07-14 05:39:41\"} ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-07-14 06:03:07', 193);
