-- ----------------------------
-- Table structure for activity
-- ----------------------------
DROP TABLE IF EXISTS `activity`;
CREATE TABLE `activity` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(100) DEFAULT NULL COMMENT '活动标题',
  `description` text COMMENT '活动描述',
  `cover` varchar(255) DEFAULT NULL COMMENT '活动封面',
  `type` varchar(20) DEFAULT NULL COMMENT '活动类型 discount/buy_one_get_one/new_user/distribution',
  `rule` json DEFAULT NULL COMMENT '活动规则',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `priority` int DEFAULT '0' COMMENT '优先级',
  `status` tinyint DEFAULT '0' COMMENT '状态 0-草稿 1-已上线 2-已下线',
  `join_count` int DEFAULT '0' COMMENT '参与人数',
  `order_count` int DEFAULT '0' COMMENT '订单数',
  `total_amount` decimal(10,2) DEFAULT '0.00' COMMENT '总金额',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='活动表';

