COMMIT;

-- ----------------------------
-- Table structure for ai_model_config
-- ----------------------------
DROP TABLE IF EXISTS `ai_model_config`;
CREATE TABLE `ai_model_config` (
  `model_id` bigint NOT NULL AUTO_INCREMENT COMMENT '模型配置ID',
  `provider_id` bigint NOT NULL COMMENT '提供商ID',
  `model_name` varchar(100) NOT NULL COMMENT '模型名称',
  `model_code` varchar(100) NOT NULL COMMENT '模型编码（唯一标识）',
  `model_type` varchar(20) NOT NULL COMMENT '模型类型：chat=对话模型, embedding=嵌入模型, image=图像模型',
  `api_key` varchar(500) DEFAULT NULL COMMENT 'API密钥（本地模型可为空）',
  `context_window` int DEFAULT NULL COMMENT '上下文窗口大小',
  `max_tokens` int DEFAULT NULL COMMENT '最大输出token数',
  `temperature` decimal(3,2) DEFAULT '0.70' COMMENT '温度参数（0-2）',
  `top_p` decimal(3,2) DEFAULT '1.00' COMMENT 'Top-P参数（0-1）',
  `timeout_seconds` int DEFAULT '300' COMMENT '超时时间（秒）',
  `is_default` char(1) DEFAULT '0' COMMENT '是否默认模型（0否 1是）',
  `status` char(1) DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `sort_order` int DEFAULT '0' COMMENT '排序顺序',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`model_id`),
  UNIQUE KEY `uk_model_code` (`model_code`),
  KEY `idx_provider_id` (`provider_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI模型配置表';

