  `parameters` text COLLATE utf8mb4_unicode_ci COMMENT '参数（JSON格式）',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '行为描述',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态：0启用 1禁用',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`action_id`),
  KEY `idx_action_concept` (`concept_id`),
  KEY `idx_action_code` (`action_code`),
  CONSTRAINT `ai_ontology_action_ibfk_1` FOREIGN KEY (`concept_id`) REFERENCES `ai_ontology_concept` (`concept_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='行为表';

