-- ----------------------------
-- Table structure for ai_session_config
-- ----------------------------
DROP TABLE IF EXISTS `ai_session_config`;
CREATE TABLE `ai_session_config` (
  `config_id` bigint NOT NULL AUTO_INCREMENT COMMENT '配置ID',
