  `embedding_model_id` bigint DEFAULT NULL COMMENT '嵌入模型ID',
  `max_history_messages` int DEFAULT '20' COMMENT '最大历史消息数',
  `enable_rag` char(1) DEFAULT '0' COMMENT '是否启用RAG（0否 1是）',
  `rag_max_results` int DEFAULT '3' COMMENT 'RAG检索结果数量',
  `rag_min_score` decimal(3,2) DEFAULT '0.50' COMMENT 'RAG最小相似度',
  `system_prompt` text COMMENT '系统提示词',
  `is_default` char(1) DEFAULT '0' COMMENT '是否默认配置（0否 1是）',
  `status` char(1) DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `config_key` varchar(50) DEFAULT NULL COMMENT '配置标识键（platform/mobile/ontology/nl2sql），用于代码中按场景查找配置',
  PRIMARY KEY (`config_id`),
  KEY `idx_chat_model_id` (`chat_model_id`),
  KEY `idx_embedding_model_id` (`embedding_model_id`),
  KEY `idx_config_key` (`config_key`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI会话配置表';

