DROP TABLE IF EXISTS `audio_item`;
CREATE TABLE `audio_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `file_id` bigint DEFAULT NULL COMMENT '文件记录ID',
  `cover_file_id` bigint DEFAULT NULL COMMENT '封面文件ID',
