COMMIT;

-- ----------------------------
-- Table structure for distributor
-- ----------------------------
DROP TABLE IF EXISTS `distributor`;
CREATE TABLE `distributor` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `level` tinyint DEFAULT '1' COMMENT '等级 1-普通 2-高级 3-金牌',
  `real_name` varchar(50) DEFAULT NULL COMMENT '真实姓名',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `alipay_account` varchar(50) DEFAULT NULL COMMENT '支付宝账号',
  `wechat_account` varchar(50) DEFAULT NULL COMMENT '微信账号',
  `total_commission` decimal(10,2) DEFAULT '0.00' COMMENT '累计佣金',
  `available_commission` decimal(10,2) DEFAULT '0.00' COMMENT '可提现佣金',
  `frozen_commission` decimal(10,2) DEFAULT '0.00' COMMENT '冻结佣金',
  `total_withdraw` decimal(10,2) DEFAULT '0.00' COMMENT '累计提现',
  `total_fans` int DEFAULT '0' COMMENT '累计粉丝数',
  `total_orders` int DEFAULT '0' COMMENT '累计订单数',
  `status` tinyint DEFAULT '0' COMMENT '状态 0-待审核 1-已通过 2-已拒绝 3-已禁用',
  `apply_time` datetime DEFAULT NULL COMMENT '申请时间',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` text COMMENT '审核备注',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='分销员表';

-- ----------------------------
-- Records of distributor
-- ----------------------------
BEGIN;
COMMIT;

