DROP TABLE IF EXISTS `pay_transaction`;
CREATE TABLE `pay_transaction` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(50) DEFAULT NULL COMMENT '订单号',
  `transaction_id` varchar(50) DEFAULT NULL COMMENT '第三方交易号',
  `pay_type` varchar(20) DEFAULT NULL COMMENT '支付方式',
  `amount` decimal(10,2) DEFAULT NULL COMMENT '交易金额',
  `status` tinyint DEFAULT NULL COMMENT '状态 0-待支付 1-支付成功 2-支付失败 3-已退款',
  `pay_time` datetime DEFAULT NULL COMMENT '支付时间',
  `raw_data` text COMMENT '原始支付数据',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_order_no` (`order_no`),
  KEY `idx_transaction_id` (`transaction_id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='交易记录表';

