-- Table structure for vip_gift_record
-- ----------------------------
DROP TABLE IF EXISTS `vip_gift_record`;
CREATE TABLE `vip_gift_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rule_id` bigint DEFAULT NULL COMMENT '赠送规则ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `user_nickname` varchar(50) DEFAULT NULL COMMENT '用户昵称',
  `grant_type` varchar(20) NOT NULL COMMENT '赠送类型: auto-自动 manual-手动',
  `vip_days` int NOT NULL COMMENT '赠送天数',
  `reason` varchar(500) DEFAULT NULL COMMENT '赠送原因',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人ID(手动赠送时)',
  `operator_name` varchar(50) DEFAULT NULL COMMENT '操作人姓名',
  `expire_time` datetime DEFAULT NULL COMMENT '会员到期时间',
  `status` tinyint DEFAULT '1' COMMENT '状态 0-失效 1-有效',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_rule_id` (`rule_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='会员赠送记录表';

-- ----------------------------
-- Records of vip_gift_record
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for vip_gift_rule
-- ----------------------------
DROP TABLE IF EXISTS `vip_gift_rule`;
CREATE TABLE `vip_gift_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rule_name` varchar(100) NOT NULL COMMENT '规则名称',
  `rule_type` varchar(20) NOT NULL COMMENT '规则类型: register-注册送 invite-邀请送 focus-专注送 manual-手动赠送',
  `condition_value` varchar(500) DEFAULT NULL COMMENT '条件值(JSON)',
  `vip_days` int NOT NULL DEFAULT '0' COMMENT '赠送天数(0=终身)',
  `auto_grant` tinyint DEFAULT '0' COMMENT '是否自动发放 0-否 1-是',
  `total_limit` int DEFAULT '0' COMMENT '总名额限制(0=不限)',
  `granted_count` int DEFAULT '0' COMMENT '已发放数量',
  `daily_limit` int DEFAULT '0' COMMENT '每日限制(0=不限)',
  `status` tinyint DEFAULT '1' COMMENT '状态 0-禁用 1-启用',
  `description` varchar(500) DEFAULT NULL COMMENT '规则说明',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_rule_type` (`rule_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='会员赠送规则表';

-- ----------------------------
-- Records of vip_gift_rule
-- ----------------------------
BEGIN;
COMMIT;

