-- Table structure for withdraw_apply
-- ----------------------------
DROP TABLE IF EXISTS `withdraw_apply`;
CREATE TABLE `withdraw_apply` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `distributor_id` bigint DEFAULT NULL COMMENT '分销员ID',
  `amount` decimal(10,2) DEFAULT NULL COMMENT '提现金额',
  `fee` decimal(10,2) DEFAULT NULL COMMENT '手续费',
  `actual_amount` decimal(10,2) DEFAULT NULL COMMENT '实际到账金额',
  `pay_type` varchar(20) DEFAULT NULL COMMENT '提现方式 alipay/wechat',
  `account` varchar(50) DEFAULT NULL COMMENT '提现账号',
  `real_name` varchar(50) DEFAULT NULL COMMENT '真实姓名',
  `status` tinyint DEFAULT '0' COMMENT '状态 0-待审核 1-审核通过 2-审核拒绝 3-打款中 4-已完成',
  `audit_user_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` text COMMENT '审核备注',
  `pay_time` datetime DEFAULT NULL COMMENT '打款时间',
  `transaction_id` varchar(50) DEFAULT NULL COMMENT '打款交易号',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_distributor_id` (`distributor_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='提现申请表';

